/* ★ 「いま本体はどの上限で動いているか」を管理画面へ返すための口。
   管理画面側で同じ計算をやり直すと、本体と食い違ったときに気付けない。
   **本体が実際に使っている関数をそのまま呼ぶ。** */
setRuntimeProbe((env) => ({
  生成の上限: {
    free: lumiUsagePolicy(env, { plan: "free" }),
    byok: lumiUsagePolicy(env, { plan: "paid" })
  },
  quickMockの最大問題数: limitValue("quickmock.questions.max", SCAN_MAX_QUESTIONS),
  /* ══ 本体が **いま実際に使っている** 提供元・モデル・鍵の本数（2026-08-20）══
     ★ 訴え「管理ダッシュボードと 今の本番を 同期させたい」。
     ★ 管理画面の 上限表（provider_limit_config）は **手で入れる**もので、
       本体の 設定を 変えても ついてこない。実際に ズレていた:
         ・表は「Quick Chat の 主は Gemini」だが、本番は CHAT_PROVIDER=workers_ai
         ・鍵の 本数も 表と 実際で 食い違いうる
       ズレたまま 画面を 見ていると、**枠の 見積りが まるごと 間違う**。
     ★ だから **本体から そのまま 読んで 返す**。手で入れる値（RPM/TPM/RPD）は
       提供元が 決めるものなので これまでどおり 表に置き、
       ズレは 画面で 名指しする。 */
  AIの実際: (() => {
    try {
      const 提供元 = String(env?.CHAT_PROVIDER || "").trim().toLowerCase() || "workers_ai";
      const 生成鍵 = aigenGeminiKeys(env);
      const 話鍵 = aigenGeminiChatKeys(env);
      const 専用 = ["GEMINI_CHAT_KEY", "GEMINI_CHAT_KEY_2", "GEMINI_CHAT_KEY_3",
        "GEMINI_CHAT_KEY_4", "GEMINI_CHAT_KEY_5", "GEMINI_CHAT_KEY_6"]
        .map((n) => String(env?.[n] || "").trim()).filter((k, i, a) => k && a.indexOf(k) === i).length;
      const groq鍵 = aigenGroqKeys(env);
      const 話モデル = 提供元 === "gemini"
        ? aigenChatModels(env, false).concat(aigenChatModels(env, true))
        : [String(env?.CHAT_MODEL_PRIMARY || ""), String(env?.CHAT_MODEL_REASONING || "")];
      return {
        QuickChat: {
          提供元,
          モデル: 話モデル.filter((m, i, a) => m && a.indexOf(m) === i),
          鍵の本数: 提供元 === "gemini" ? 話鍵.length : 0,
          専用の鍵: 専用,
          生成の鍵を借りている: 提供元 === "gemini" && 専用 === 0
        },
        生成: {
          gemini: { 鍵の本数: 生成鍵.length,
            モデル: [aigenModelFor(env, "gemini", "fast"), aigenModelFor(env, "gemini", "strong")]
              .filter((m, i, a) => m && a.indexOf(m) === i) },
          groq: { 鍵の本数: groq鍵.length,
            モデル: [aigenModelFor(env, "groq", "fast"), aigenModelFor(env, "groq", "strong")]
              .filter((m, i, a) => m && a.indexOf(m) === i) },
          workers_ai: { 鍵の本数: 1,
            モデル: [String(env?.PRESET_BUILD_MODEL || ""), String(env?.PRESET_BUILD_MODEL_FALLBACK || "")]
              .filter((m, i, a) => m && a.indexOf(m) === i) }
        },
        音声会話: { モデル: LIVE_MODEL, 鍵の本数: 生成鍵.length, 一日の上限: LIVE_DAILY_MAX }
      };
    } catch (e) { return null; }
  })()
}));

