/* ══════════════════════════════════════════════════════════════════
   環境の分離（DEV-1）

   開発版 Worker から本番 D1 へ書けてしまうと、設定ミス 1 回で
   実ユーザーのデータが壊れる。VQ_ENV を見て、開発版が本番の識別子を
   掴んでいたら **リクエストを一切処理しない**。

   本番（VQ_ENV 未設定 または "production"）の挙動は変えない。
   ══════════════════════════════════════════════════════════════════ */
const PRODUCTION_D1_ID = "fe6346ac-dc7d-4a69-90a6-1919456716b2";
const PRODUCTION_D1_NAME = "vocabuquiz_auth";
const PRODUCTION_HOSTS = new Set(["vocabuquiz.app", "www.vocabuquiz.app"]);

export function isDevelopmentEnv(env) {
  return String(env?.VQ_ENV || "").trim().toLowerCase() === "development";
}

/* 問題があれば理由付きで ok:false。本番では常に ok:true。 */
export function checkEnvironmentSafety(env) {
  if (!isDevelopmentEnv(env)) return { ok: true, reasons: [] };
  const reasons = [];
  /* wrangler は database_id を env へ出さないので、名前と
     「開発版なのに本番 URL を名乗っていないか」で見る。 */
  const dbName = String(env?.D1_DATABASE_NAME || "").trim();
  if (dbName && dbName === PRODUCTION_D1_NAME)
    reasons.push("開発環境なのに本番 D1（" + PRODUCTION_D1_NAME + "）が割り当てられています");
  const dbId = String(env?.D1_DATABASE_ID || "").trim();
  if (dbId && dbId === PRODUCTION_D1_ID)
    reasons.push("開発環境なのに本番 D1 の database_id が設定されています");
  const base = String(env?.APP_BASE_URL || "").trim();
  if (base && PRODUCTION_HOSTS.has(safeHostname(base)))
    reasons.push("開発環境なのに APP_BASE_URL が本番を指しています");
  if (String(env?.CF_PAGES_API_TOKEN || "").trim())
    reasons.push("開発環境に CF_PAGES_API_TOKEN が設定されています");
  if (String(env?.RESEND_API_KEY || "").trim())
    reasons.push("開発環境に RESEND_API_KEY が設定されています（実メールを送ってしまいます）");
  return { ok: reasons.length === 0, reasons };
}
function safeHostname(u) {
  try { return new URL(u).hostname.toLowerCase(); } catch { return ""; }
}

