const KIMI_K2_MODEL = "@cf/moonshotai/kimi-k2.6";
const KIMI_K2_MAX_TOKENS = 65536;

/* K2.6 容量上限 (3040) は短時間で解消するので指数バックオフでリトライ */
async function _runKimiWithRetry(env, params, opts = {}) {
  const maxRetries = Math.max(0, Number(opts.maxRetries ?? 3));
  const delays = [2000, 5000, 10000]; /* 1st retry: 2s, 2nd: 5s, 3rd: 10s */
  let lastErr = null;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await env.AI.run(KIMI_K2_MODEL, params);
    } catch (e) {
      lastErr = e;
      const msg = String(e?.message || "");
      const isCapacity = /3040|capacity|rate.?limit|429|503|overloaded|temporarily/i.test(msg);
      if (!isCapacity || i >= maxRetries) throw e;
      if (typeof opts.onRetry === "function") {
        try { await opts.onRetry(i + 1, delays[i]); } catch {}
      }
      await new Promise(r => setTimeout(r, delays[i]));
    }
  }
  throw lastErr;
}

