const SEDE_FIX_MAX_TOKENS = 16384;

/* Kimi K2.6 retry 付きフォールバック (retry 3回 → GLM) */
async function _sedeRunAI(env, params, opts = {}) {
  const maxTokens = params.max_tokens || KIMI_K2_MAX_TOKENS;
  const temp = params.temperature ?? 0.3;
  /* 1. Kimi K2.6 with internal retry (2s/5s/10s) */
  try {
    return await _runKimiWithRetry(env, { ...params, max_tokens: maxTokens, temperature: temp });
  } catch (e) {
    console.warn("[SedeAI] Kimi K2.6 all retries exhausted:", String(e?.message || "").slice(0, 150));
  }
  /* 2. GLM 4.7 Flash (最終フォールバック) */
  return await env.AI.run(SEDE_MODEL_GLM, { ...params, max_tokens: Math.min(maxTokens, 32768), temperature: temp + 0.1 });
}

const SEDE_COMMANDS = new Set(["create","fix","run","extend","deploy","explain","search"]);

function detectSedeAction(text, existingCodeLines) {
  const t = String(text || "").trim();
  const lines = Math.max(0, Number(existingCodeLines) || 0);
  if (t.startsWith("/create")) return { action: "create", cmd: "/create" };
  if (t.startsWith("/fix")) return { action: "fix", cmd: "/fix" };
  if (t.startsWith("/run")) return { action: "run", cmd: "/run" };
  if (t.startsWith("/extend")) return { action: "extend", cmd: "/extend" };
  if (t.startsWith("/deploy")) return { action: "deploy", cmd: "/deploy" };
  if (t.startsWith("/explain")) return { action: "explain", cmd: "/explain" };
  if (t.startsWith("/search")) return { action: "search", cmd: "/search" };
  /* Auto-detect from content */
  if (/(作って|作成|generate|build|新規|create)/i.test(t) && !existingCodeLines) return { action: "create", cmd: null };
  if (/(修正|バグ|fix|debug|エラー|error|直して)/i.test(t)) return { action: "fix", cmd: null };
  if (/(追加|拡張|extend|add|機能|feature)/i.test(t) && existingCodeLines > 0) return { action: "extend", cmd: null };
  if (/(説明|explain|what|どういう|解説)/i.test(t)) return { action: "explain", cmd: null };
  return { action: "chat", cmd: null };
}

function selectSedeModel(action, codeLines) {
  if (action === "chat" || action === "explain") return SEDE_MODEL_GLM;
  return SEDE_MODEL_KIMI; /* All code actions → Kimi K2.6 */
}

