/* ── Firebase の ID トークンを検証する ─────────────────────────────
   外部ライブラリを足さない。WebCrypto だけで済ませる。
   公開鍵は JWK の形で配られているものを使う（X.509 を自前で解く必要がない）。 */
const FIREBASE_JWKS_URL =
  "https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com";
let _fbKeys = { at: 0, ttl: 0, map: null };

function b64urlToBytes(s) {
  const t = String(s).replace(/-/g, "+").replace(/_/g, "/");
  const pad = t.length % 4 ? "====".slice(t.length % 4) : "";
  const bin = atob(t + pad);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
function b64urlToJson(s) {
  return JSON.parse(new TextDecoder().decode(b64urlToBytes(s)));
}
async function firebasePublicKeys() {
  const now = Date.now();
  if (_fbKeys.map && now < _fbKeys.at + _fbKeys.ttl) return _fbKeys.map;
  const res = await fetch(FIREBASE_JWKS_URL);
  if (!res.ok) throw Object.assign(new Error("JWKS_FETCH_FAILED"), { code: "JWKS_FETCH_FAILED", status: 502 });
  const body = await res.json();
  const map = {};
  for (const jwk of (body.keys || [])) {
    if (!jwk.kid) continue;
    map[jwk.kid] = jwk;
  }
  /* Cache-Control の max-age を尊重する。無ければ 1 時間。 */
  let ttl = 3600000;
  const cc = String(res.headers.get("cache-control") || "");
  const m = /max-age=(\d+)/.exec(cc);
  if (m) ttl = Math.max(60000, Number(m[1]) * 1000);
  _fbKeys = { at: now, ttl, map };
  return map;
}
function firebaseProjectId(env) {
  return String(env?.FIREBASE_PROJECT_ID || "vocabuquiz").trim();
}
async function firebaseVerifyIdToken(env, idToken) {
  const raw = String(idToken || "").trim();
  const parts = raw.split(".");
  const bad = (code, message) => Object.assign(new Error(code), { code, status: 401, message });
  if (parts.length !== 3) throw bad("BAD_TOKEN", "ログイン情報の形式が正しくありません。");

  let header, payload;
  try {
    header = b64urlToJson(parts[0]);
    payload = b64urlToJson(parts[1]);
  } catch { throw bad("BAD_TOKEN", "ログイン情報を読み取れませんでした。"); }

  if (String(header.alg) !== "RS256") throw bad("BAD_ALG", "ログイン情報の署名方式が想定と違います。");
  if (!header.kid) throw bad("BAD_TOKEN", "ログイン情報に鍵の指定がありません。");

  const keys = await firebasePublicKeys();
  const jwk = keys[header.kid];
  if (!jwk) throw bad("UNKNOWN_KEY", "ログイン情報の鍵が見つかりません。時間をおいてお試しください。");

  const key = await crypto.subtle.importKey(
    "jwk",
    { kty: jwk.kty, n: jwk.n, e: jwk.e, alg: "RS256", ext: true },
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["verify"]
  );
  const okSig = await crypto.subtle.verify(
    "RSASSA-PKCS1-v1_5",
    key,
    b64urlToBytes(parts[2]),
    new TextEncoder().encode(parts[0] + "." + parts[1])
  );
  if (!okSig) throw bad("BAD_SIGNATURE", "ログイン情報の署名が正しくありません。");

  const projectId = firebaseProjectId(env);
  const nowSec = Math.floor(Date.now() / 1000);
  const skew = 300;
  if (String(payload.aud) !== projectId) throw bad("BAD_AUDIENCE", "別のアプリ向けのログイン情報です。");
  if (String(payload.iss) !== "https://securetoken.google.com/" + projectId)
    throw bad("BAD_ISSUER", "ログイン情報の発行元が正しくありません。");
  if (!(Number(payload.exp) > nowSec - skew)) throw bad("TOKEN_EXPIRED", "ログイン情報の期限が切れています。もう一度お試しください。");
  if (Number(payload.iat) > nowSec + skew) throw bad("TOKEN_FUTURE", "端末の時計がずれている可能性があります。");
  if (payload.auth_time && Number(payload.auth_time) > nowSec + skew) throw bad("TOKEN_FUTURE", "端末の時計がずれている可能性があります。");
  const sub = String(payload.sub || "").trim();
  if (!sub) throw bad("BAD_SUBJECT", "ログイン情報に利用者の識別子がありません。");

  const signIn = String(payload.firebase?.sign_in_provider || "").trim();
  if (!SOCIAL_PROVIDERS[signIn])
    throw bad("PROVIDER_NOT_ALLOWED", "この方法でのログインには対応していません。");

  return {
    provider: signIn,
    providerId: SOCIAL_PROVIDERS[signIn].id,
    providerLabel: SOCIAL_PROVIDERS[signIn].label,
    subject: sub,
    email: String(payload.email || "").trim().toLowerCase(),
    emailVerified: payload.email_verified === true,
    displayName: String(payload.name || "").slice(0, 80),
    photoUrl: String(payload.picture || "").slice(0, 500)
  };
}

/* ── 画像・動画の置き場所（R2 が無いときの控え）─────────────────
   本来の置き場所は R2（MEDIA_R2）。ただし R2 は Cloudflare の管理画面で
   有効にしないと使えず、それが済むまで投稿へ画像も動画も付けられなくなる。

   そこで、R2 が無いときだけ D1 へ入れる。
   D1 は 1 行 2MB までなので、700KB ずつに切って複数行に分けて持つ。
   ・R2 があるときは、この経路は 1 度も通らない（今までどおり R2 が使われる）
   ・切り分けた実体は media_blobs、大きさや種類は media_blob_meta が持つ
   ────────────────────────────────────────────────────────────── */
const MEDIA_TABLES = [
  `CREATE TABLE IF NOT EXISTS media_blob_meta (
    key TEXT PRIMARY KEY,
    content_type TEXT NOT NULL DEFAULT '',
    size INTEGER NOT NULL DEFAULT 0,
    parts INTEGER NOT NULL DEFAULT 0,
    user_id INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL DEFAULT 0)`,
  `CREATE TABLE IF NOT EXISTS media_blobs (
    key TEXT NOT NULL,
    part INTEGER NOT NULL,
    bytes BLOB NOT NULL,
    PRIMARY KEY (key, part))`,
  `CREATE INDEX IF NOT EXISTS idx_media_blob_meta_user ON media_blob_meta(user_id, created_at)`
];

/* ── 会話（Quick Chat / Lumi）の置き場所 ─────────────────────────
   なぜ要るか（2026-08-19・実測）:
     会話の一覧（app.chat.sessions.v2）と 各会話の本文（app.chat.ses.<id>.v2）は
     **端末の中にしか無かった**。localStorage の上限は 実測 4.4MB で、
     すでに 4.6MB 使っていた。つまり **会話は 増えるほど 消えていた**し、
     端末を変えれば 何も残らなかった。

     いま在るサーバ側の入れ物は どちらも 会話一覧を持てない:
       ・chat_history … いま開いている会話の本文を 1 人 1 行の JSON で持つ
       ・sync_chats  … その本文を 1 通ずつに割ったもの
     どちらも「会話が何本あるか」を知らない。だからここを新しく作る。

   形:
     1 会話 = 1 行。本文は body_json に そのまま入れる。
     D1 は 1 行 2MB まで（STORAGE_LIMITS.rowBytes）なので、
     それを超える会話は **入れずに断る**（黙って切らない）。
     消したものは deleted_at を立てて残す（端末をまたいだ復活を防ぐ）。
   ────────────────────────────────────────────────────────────── */
const CHAT_SESSION_TABLES = [
  `CREATE TABLE IF NOT EXISTS chat_sessions (
    user_id INTEGER NOT NULL,
    id TEXT NOT NULL,
    title TEXT NOT NULL DEFAULT '',
    meta_json TEXT NOT NULL DEFAULT '{}',
    body_json TEXT NOT NULL DEFAULT '[]',
    updated_at INTEGER NOT NULL DEFAULT 0,
    deleted_at INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, id))`,
  `CREATE INDEX IF NOT EXISTS idx_chat_sessions_user ON chat_sessions(user_id, updated_at DESC)`
];

