    const ensureCols = async (table, defs) => {
      const info = await safeTableInfo(table);
      if (!info) return;
      /* ══ 無い表へ ALTER をかけない ═════════════════════════════════
         PRAGMA table_info は **表が無くても例外を投げず、空を返す**。
         そのまま進むと ALTER TABLE で落ち、そこで схема の作り直しが
         丸ごと止まって **すべての API が 500 になる**
         （実測 2026-08-12: lumi_usage を足した直後に全滅した）。
         列が 0 個 ＝ その表は無い。触らずに帰る。 */
      const have = new Set((info?.results || []).map((r) => String(r?.name || "")));
      if (!have.size) return;
      for (const def of defs) {
        const col = String(def.name || "");
        const ddl = String(def.ddl || "").trim();
        if (!col || !ddl || have.has(col)) continue;
        await env.DB.prepare(`ALTER TABLE ${table} ADD COLUMN ${ddl}`).run();
      }
    };

