    const tableCols = async (table) => {
      const info = await safeTableInfo(table);
      if (!info) return null;
      return new Set((info?.results || []).map((r) => String(r?.name || "")));
    };
    const migrateText = async (table, cols, toCol, fromCol) => {
      if (!cols.has(toCol) || !cols.has(fromCol) || toCol === fromCol) return;
      try {
        await env.DB.prepare(
          `UPDATE ${table} SET "${toCol}" = CASE WHEN ("${toCol}" IS NULL OR "${toCol}" = '') THEN COALESCE("${fromCol}", "${toCol}") ELSE "${toCol}" END`
        ).run();
      } catch {}
    };
    const migrateInt = async (table, cols, toCol, fromCol) => {
      if (!cols.has(toCol) || !cols.has(fromCol) || toCol === fromCol) return;
      try {
        await env.DB.prepare(
          `UPDATE ${table} SET "${toCol}" = CASE WHEN ("${toCol}" IS NULL OR "${toCol}" = 0) THEN COALESCE("${fromCol}", "${toCol}") ELSE "${toCol}" END`
        ).run();
      } catch {}
    };

    const usersCols = await tableCols("users");
    if (usersCols) {
      await migrateText("users", usersCols, "grade_prefix", "gradePrefix");
      await migrateText("users", usersCols, "nickname_norm", "nicknameNorm");
      await migrateText("users", usersCols, "pass_hash", "passHash");
      await migrateText("users", usersCols, "pass_salt", "passSalt");
      await migrateInt("users", usersCols, "pass_iter", "passIter");
      await migrateInt("users", usersCols, "failed_attempts", "failedAttempts");
      await migrateInt("users", usersCols, "lock_until", "lockUntil");
      await migrateInt("users", usersCols, "tos_accepted_at", "tosAcceptedAt");
      await migrateText("users", usersCols, "tos_version", "tosVersion");
      await migrateInt("users", usersCols, "created_at", "createdAt");
      await migrateInt("users", usersCols, "updated_at", "updatedAt");
      await migrateInt("users", usersCols, "last_login_at", "lastLoginAt");
    }

    const sessCols = await tableCols("auth_sessions");
    if (sessCols) {
      await migrateInt("auth_sessions", sessCols, "user_id", "userId");
      await migrateText("auth_sessions", sessCols, "token_hash", "tokenHash");
      await migrateInt("auth_sessions", sessCols, "created_at", "createdAt");
      await migrateInt("auth_sessions", sessCols, "updated_at", "updatedAt");
      await migrateInt("auth_sessions", sessCols, "expires_at", "expiresAt");
      await migrateText("auth_sessions", sessCols, "user_agent", "userAgent");
    }

    const sharesCols = await tableCols("shares");
    if (sharesCols) {
      await migrateText("shares", sharesCols, "app_version", "appVersion");
      await migrateInt("shares", sharesCols, "schema_version", "schemaVersion");
      await migrateText("shares", sharesCols, "preset_json", "presetJson");
      await migrateInt("shares", sharesCols, "created_at", "createdAt");
      await migrateInt("shares", sharesCols, "expires_at", "expiresAt");
    }

    const followsCols = await tableCols("user_follows");
    if (followsCols?.has("requested_at") && followsCols?.has("approved_at")) {
      try {
        await env.DB.prepare(`
          UPDATE user_follows
          SET requested_at = CASE
              WHEN requested_at = 0 AND deleted_at = 0
                THEN CASE
                  WHEN created_at > 0 THEN created_at
                  WHEN updated_at > 0 THEN updated_at
                  ELSE CAST(strftime('%s','now') AS INTEGER) * 1000
                END
              ELSE requested_at
            END,
            approved_at = CASE
              WHEN approved_at = 0 AND deleted_at = 0 AND requested_at = 0
                THEN CASE
                  WHEN updated_at > 0 THEN updated_at
                  WHEN created_at > 0 THEN created_at
                  ELSE CAST(strftime('%s','now') AS INTEGER) * 1000
                END
              ELSE approved_at
            END
        `).run();
      } catch {}
    }

