function normalizeMode(raw) {
  const v = String(raw || "").trim().toLowerCase();
  if (v === MODE_SEED_PRO || v === "seed-pro" || v === "seed_pro") return MODE_SEED_PRO;
  if (v === MODE_SEED_THINKING || v === "deepthink" || v === "deep_think" || v === "seed-thinking" || v === "seed_thinking") return MODE_SEED_THINKING;
  if (v === MODE_CODE || v === "code" || v === "sede") return MODE_CODE;
  if (v === CHAT_PUBLIC_MODE_PROFESSOR || v === "reason" || v === "reasoning" || v === "deep" || v === "precision") return MODE_REASONING;
  return MODE_NORMAL;
}

function isSeedMode(mode) {
  return mode === MODE_SEED_PRO || mode === MODE_SEED_THINKING || mode === MODE_CODE;
}

function publicChatMode(mode) {
  if (mode === MODE_SEED_PRO) return CHAT_PUBLIC_MODE_SEED_PRO;
  if (mode === MODE_SEED_THINKING) return CHAT_PUBLIC_MODE_SEED_THINKING;
  if (mode === MODE_CODE) return "code";
  return normalizeMode(mode) === MODE_REASONING ? CHAT_PUBLIC_MODE_PROFESSOR : CHAT_PUBLIC_MODE_STANDARD;
}

function modelForMode(env, mode) {
  const hasOpenAi = openAiEnabled(env);
  if (mode === MODE_REASONING) {
    const preferred = String(
      env.MODEL_REASON
      || env.AI_MODEL_REASONING
      || "gpt-5.2"
    ).trim();
    if (isOpenAiModelName(preferred) && !hasOpenAi) {
      return String(env.AI_MODEL_REASONING || "@cf/meta/llama-3.1-8b-instruct").trim();
    }
    return preferred;
  }
  const preferred = String(
    env.MODEL_NORMAL
    || env.AI_MODEL_NORMAL
    || "gpt-5-mini"
  ).trim();
  if (isOpenAiModelName(preferred) && !hasOpenAi) {
    return String(env.AI_MODEL_NORMAL || "@cf/meta/llama-3.1-8b-instruct-fp8-fast").trim();
  }
  return preferred;
}

function isMetaLlamaModel(model) {
  const v = String(model || "").trim().toLowerCase();
  if (!v) return false;
  return v.includes("llama");
}

function firstNonEmpty(values, fallback = "") {
  for (const value of (Array.isArray(values) ? values : [])) {
    const text = String(value || "").trim();
    if (text) return text;
  }
  return String(fallback || "").trim();
}

function chatProviderPreference(env) {
  const raw = String(env?.CHAT_PROVIDER || "").trim().toLowerCase();
  if (raw === CHAT_PROVIDER_OPENAI_COMPAT) return CHAT_PROVIDER_OPENAI_COMPAT;
  return CHAT_PROVIDER_WORKERS_AI;
}

// VQ AI ONE MAX の切替点: env.CHAT_MODEL_PRIMARY / env.CHAT_MODEL_REASONING を差し替えるだけで
// Meta Llama 系モデルを将来入れ替えられるようにしている。
function chatModelForMode(env, mode) {
  const fallback = mode === MODE_REASONING ? CHAT_DEFAULT_META_REASON_MODEL : CHAT_DEFAULT_META_MODEL;
  const candidates = mode === MODE_REASONING
    ? [
        env?.CHAT_MODEL_REASONING,
        env?.CHAT_META_MODEL_REASONING,
        env?.CHAT_MODEL_PRIMARY,
        env?.CHAT_META_MODEL_PRIMARY,
        env?.AI_MODEL_REASONING,
        env?.AI_MODEL_NORMAL
      ]
    : [
        env?.CHAT_MODEL_PRIMARY,
        env?.CHAT_META_MODEL_PRIMARY,
        env?.CHAT_MODEL_REASONING,
        env?.CHAT_META_MODEL_REASONING,
        env?.AI_MODEL_NORMAL,
        env?.AI_MODEL_REASONING
      ];
  const preferred = firstNonEmpty(candidates, fallback);
  return isMetaLlamaModel(preferred) ? preferred : fallback;
}

function isOpenAiModelName(model) {
  return /^gpt-/i.test(String(model || "").trim());
}

function openAiEnabled(env) {
  return !!String(env?.OPENAI_API_KEY || "").trim();
}

function sanitizeProviderForModel(env, model) {
  const hasWorkersAi = !!(env?.AI && typeof env.AI.run === "function");
  const hasOpenAi = openAiEnabled(env);
  if (isOpenAiModelName(model) && hasOpenAi) return "openai";
  if (hasWorkersAi) return "workers_ai";
  if (hasOpenAi) return "openai";
  return "";
}

function chatMaxTokensForMode(env, mode) {
  const fallback = mode === MODE_REASONING
    ? CHAT_DEFAULT_MAX_TOKENS[MODE_REASONING]
    : CHAT_DEFAULT_MAX_TOKENS[MODE_NORMAL];
  const raw = mode === MODE_REASONING
    ? env?.CHAT_MAX_TOKENS_REASONING
    : env?.CHAT_MAX_TOKENS_NORMAL;
  const parsed = Number(raw);
  if (Number.isFinite(parsed) && parsed >= 128) return Math.max(128, Math.min(16384, Math.trunc(parsed)));
  return fallback;
}

function dailyLimitsForPlan(isPaid) {
  return isPaid ? DAILY_LIMITS_PAID : DAILY_LIMITS_FREE;
}
function dailyLimitForMode(mode, isPaid) {
  const limits = dailyLimitsForPlan(isPaid);
  return mode === MODE_REASONING ? limits[MODE_REASONING] : limits[MODE_NORMAL];
}

function jstDateKey(ts = Date.now()) {
  const shifted = Number(ts || Date.now()) + 9 * 60 * 60 * 1000;
  const d = new Date(shifted);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function nextJstResetMs(ts = Date.now()) {
  const shifted = Number(ts || Date.now()) + 9 * 60 * 60 * 1000;
  const d = new Date(shifted);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  const day = d.getUTCDate();
  return Date.UTC(y, m, day + 1, 0, 0, 0) - 9 * 60 * 60 * 1000;
}

function toSafeString(v, maxLen = 2000) {
  const s = String(v || "").trim();
  if (!s) return "";
  return s.length > maxLen ? s.slice(0, maxLen) : s;
}

function normalizeForSearch(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[\u3000\s]+/g, " ")
    .replace(/[!"#$%&'()*+,./:;<=>?@[\\\]^_`{|}~-]/g, " ")
    .trim();
}

function tokenize(text, max = 48) {
  const src = normalizeForSearch(text);
  if (!src) return [];
  const out = [];
  const seen = new Set();
  const re = /([a-z0-9_#.-]{2,}|[一-龯ぁ-んァ-ヶー]{2,})/g;
  let m;
  while ((m = re.exec(src))) {
    const token = String(m[1] || "").trim();
    if (!token || seen.has(token)) continue;
    seen.add(token);
    out.push(token);
    if (out.length >= max) break;
  }
  return out;
}

function normalizeForSearchLoose(text) {
  const src = String(text || "");
  try {
    return normalizeForSearch(src.normalize("NFKC"));
  } catch {
    return normalizeForSearch(src);
  }
}

function tokenizeLoose(text, max = 48) {
  const src = normalizeForSearchLoose(text);
  if (!src) return [];
  const out = [];
  const seen = new Set();
  const re = /([a-z0-9_#.-]{2,}|[一-龯ぁ-んァ-ヶー]{1,})/g;
  let m;
  while ((m = re.exec(src))) {
    const token = String(m[1] || "").trim();
    if (!token || seen.has(token)) continue;
    seen.add(token);
    out.push(token);
    if (out.length >= max) break;
  }
  return out;
}

function clampInt(v, min, max) {
  const n = Number(v);
  if (!Number.isFinite(n)) return min;
  return Math.max(min, Math.min(max, Math.trunc(n)));
}

function formatDatePartsForTimezone(ts, timeZone) {
  const tz = String(timeZone || "Asia/Tokyo");
  try {
    const dtf = new Intl.DateTimeFormat("ja-JP", {
      timeZone: tz,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23"
    });
    const parts = dtf.formatToParts(new Date(Number(ts) || Date.now()));
    const get = (type) => parts.find((p) => p.type === type)?.value || "";
    const y = get("year");
    const m = get("month");
    const d = get("day");
    const hh = get("hour");
    const mm = get("minute");
    return {
      ymd: `${y}-${m}-${d}`,
      hm: `${hh}:${mm}`,
      tz
    };
  } catch {
    const d = new Date(Number(ts) || Date.now());
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const da = String(d.getDate()).padStart(2, "0");
    const hh = String(d.getHours()).padStart(2, "0");
    const mm = String(d.getMinutes()).padStart(2, "0");
    return {
      ymd: `${y}-${m}-${da}`,
      hm: `${hh}:${mm}`,
      tz: tz || "local"
    };
  }
}

function formatRegionFromCf(cf) {
  const src = (cf && typeof cf === "object") ? cf : {};
  const parts = [
    String(src.country || "").trim(),
    String(src.region || "").trim(),
    String(src.city || "").trim()
  ].filter(Boolean);
  if (parts.length) return parts.join(" / ");
  const fallback = String(src.colo || "").trim();
  return fallback || "不明";
}

function maskIpAddress(raw) {
  const ip = String(raw || "").trim();
  if (!ip) return "";
  if (ip.includes(":")) {
    const parts = ip.split(":");
    return parts.slice(0, 3).join(":") + ":***";
  }
  const seg = ip.split(".");
  if (seg.length !== 4) return ip;
  return `${seg[0]}.${seg[1]}.${seg[2]}.***`;
}

function getSearchKv(env) {
  const candidates = ["SEARCH_KV", "RAG_KV", "CONTENT_KV", "DOCS_KV"];
  for (const name of candidates) {
    const kv = env?.[name];
    if (kv && typeof kv.get === "function") return kv;
  }
  return null;
}

function parseSearchArray(raw, fallbackKey) {
  if (!raw) return [];
  let data = null;
  try {
    data = JSON.parse(raw);
  } catch {
    return [];
  }
  if (Array.isArray(data)) return data;
  if (data && typeof data === "object") {
    const asArray = data.docs || data.items || data.rows || data.data || data[fallbackKey];
    if (Array.isArray(asArray)) return asArray;
  }
  return [];
}

function makeSearchItem(input, source, index) {
  const row = (input && typeof input === "object") ? input : {};
  const type = (source === "vocab")
    ? "vocab"
    : (source === "insight" ? "insight" : "site");
  const id = toSafeString(row.id || `${type}-${index + 1}`, 120) || `${type}-${index + 1}`;
  let url = toSafeString(row.url || row.link || "", 500);
  const baseTags = Array.isArray(row.tags) ? row.tags.map((t) => toSafeString(t, 40)).filter(Boolean).slice(0, 20) : [];
  let title = toSafeString(row.title || row.name || row.page || "Untitled", 200);
  let text = toSafeString(row.text || row.content || row.body || row.description || "", 120000);
  let tags = baseTags.slice();
  const meta = {};
  if (type === "vocab") {
    const term = toSafeString(row.term || row.word || row.title || "", 200);
    const reading = toSafeString(row.reading || row.yomi || "", 200);
    const meaning = toSafeString(row.meaning || row.definition || "", 2000);
    const examples = Array.isArray(row.examples) ? row.examples.map((x) => toSafeString(x, 500)).filter(Boolean).slice(0, 8) : [];
    const related = Array.isArray(row.related) ? row.related.map((x) => toSafeString(x, 120)).filter(Boolean).slice(0, 20) : [];
    title = term || title;
    text = [term, reading, meaning, examples.join(" "), related.join(" "), text].filter(Boolean).join("\n");
    tags = Array.from(new Set(tags.concat(related.slice(0, 6))));
    meta.vocab = { term: term || title, reading, meaning, examples, related };
  } else if (type === "insight") {
    const payload = (row.payload && typeof row.payload === "object") ? row.payload : null;
    if (!url && payload) {
      url = toSafeString(payload.url || payload.link || "", 500);
    }
    const payloadText = payload
      ? [
          toSafeString(payload.text || "", 4000),
          toSafeString(payload.summary || "", 2000),
          toSafeString(JSON.stringify(payload.metrics || {}), 2000)
        ].filter(Boolean).join("\n")
      : "";
    text = [text, payloadText].filter(Boolean).join("\n");
    meta.insight = { payload: payload || null };
  }
  const updatedAt = Number(row.updatedAt || row.ts || row.timestamp || 0) || 0;
  const merged = `${title}\n${tags.join(" ")}\n${text}`;
  return {
    id,
    type,
    title,
    url,
    text,
    tags,
    source: type,
    updatedAt,
    meta,
    norm: normalizeForSearchLoose(merged),
    normTitle: normalizeForSearchLoose(title),
    normTags: normalizeForSearchLoose(tags.join(" ")),
    tokens: tokenizeLoose(merged, 80)
  };
}

async function loadSearchIndex(env, force = false) {
  const now = Date.now();
  if (!force && _searchCache.fetchedAt > 0 && (now - _searchCache.fetchedAt) < SEARCH_CACHE_MS) {
    return _searchCache.items;
  }
  const kv = getSearchKv(env);
  if (!kv) {
    _searchCache = { items: [], byId: new Map(), fetchedAt: now };
    return _searchCache.items;
  }
  const [docsRaw, vocabRaw, insightsRaw] = await Promise.all([
    kv.get("docs.json", "text"),
    kv.get("vocab.json", "text"),
    kv.get("insights.json", "text")
  ]);
  const docs = parseSearchArray(docsRaw, "docs");
  const vocab = parseSearchArray(vocabRaw, "vocab");
  const insights = parseSearchArray(insightsRaw, "insights");
  const items = [];
  for (let i = 0; i < docs.length; i += 1) {
    const item = makeSearchItem(docs[i], "site", i);
    if (!item.text && !item.title) continue;
    items.push(item);
  }
  for (let i = 0; i < vocab.length; i += 1) {
    const item = makeSearchItem(vocab[i], "vocab", i);
    if (!item.text && !item.title) continue;
    items.push(item);
  }
  for (let i = 0; i < insights.length; i += 1) {
    const item = makeSearchItem(insights[i], "insight", i);
    if (!item.text && !item.title) continue;
    items.push(item);
  }
  const byId = new Map();
  for (const item of items) byId.set(item.id, item);
  _searchCache = { items, byId, fetchedAt: now };
  return items;
}

function searchScore(item, qNorm, qTokens) {
  let score = 0;
  if (!item || !item.norm) return 0;
  if (qNorm && item.normTitle.includes(qNorm)) score += 120;
  else if (qNorm && item.norm.includes(qNorm)) score += 70;
  for (const token of qTokens) {
    if (!token) continue;
    if (item.normTitle.includes(token)) score += 24;
    if (item.normTags.includes(token)) score += 18;
    if (item.norm.includes(token)) score += 8;
    if (item.tokens.includes(token)) score += 3;
  }
  if (score > 0 && item.source === "insights") score += 2;
  if (score > 0 && item.updatedAt > 0) {
    const ageDays = Math.max(0, (Date.now() - item.updatedAt) / 86400000);
    score += Math.max(0, 5 - Math.floor(ageDays / 14));
  }
  return score;
}

function makeSnippet(text, queryRaw, maxLen = 200) {
  const src = String(text || "").replace(/\s+/g, " ").trim();
  if (!src) return "";
  const q = String(queryRaw || "").trim().toLowerCase();
  if (!q) return src.slice(0, maxLen);
  const lower = src.toLowerCase();
  let idx = lower.indexOf(q);
  if (idx < 0) {
    const tokens = q.split(/\s+/).filter(Boolean);
    for (const t of tokens) {
      idx = lower.indexOf(t);
      if (idx >= 0) break;
    }
  }
  if (idx < 0) return src.slice(0, maxLen);
  const half = Math.floor(maxLen / 2);
  const start = Math.max(0, idx - half);
  const end = Math.min(src.length, start + maxLen);
  const head = start > 0 ? "…" : "";
  const tail = end < src.length ? "…" : "";
  return `${head}${src.slice(start, end)}${tail}`;
}

function normalizeSearchType(raw) {
  const t = String(raw || "").trim().toLowerCase();
  if (t === "facts" || t === "fact") return "facts";
  if (t === "chunks" || t === "chunk" || t === "site") return "chunks";
  if (t === "insights" || t === "insight") return "insights";
  if (t === "procedures" || t === "procedure" || t === "propose") return "procedures";
  if (t === "all" || t === "" || t === "auto") return "all";
  return "all";
}

function normalizeSetKey(raw) {
  return normalizeForSearchLoose(String(raw || "")).replace(/\s+/g, "_");
}

function normalizeTags(raw) {
  if (!Array.isArray(raw)) return [];
  const set = new Set();
  for (const row of raw) {
    const v = toSafeString(row, 50);
    if (!v) continue;
    set.add(v);
    if (set.size >= 20) break;
  }
  return Array.from(set);
}

function toEpochMs(raw) {
  if (typeof raw === "number" && Number.isFinite(raw)) return Math.trunc(raw);
  if (typeof raw === "string" && raw.trim()) {
    const n = Number(raw);
    if (Number.isFinite(n)) return Math.trunc(n);
    const p = Date.parse(raw);
    if (Number.isFinite(p)) return Math.trunc(p);
  }
  return 0;
}

function emptyDataPack(now = Date.now(), sourceId = "pack-empty") {
  return {
    schemaVersion: 1,
    updatedAt: now,
    source_id: sourceId,
    facts: [],
    chunks: [],
    procedures: [],
    vocab: [],
    insights: []
  };
}

