async function handleVocabAsk(request, env) {
  const body = await readJsonBody(request, 32 * 1024);
  const term = toSafeString(body?.term || "", 300);
  if (!term) {
    return json({ ok: false, code: "EMPTY_TERM", message: "term を指定してください。" }, 400);
  }
  const pack = await loadDataPack(env);
  const vocab = Array.isArray(pack.vocab) ? pack.vocab : [];
  if (!vocab.length) {
    return json({ ok: false, code: "VOCAB_NOT_READY", message: "data_pack.vocab が未登録です。" }, 404);
  }
  const q = normalizeForSearchLoose(term);
  let best = null;
  let bestScore = -1;
  for (const row of vocab) {
    const termNorm = normalizeForSearchLoose(row.term || "");
    const readingNorm = normalizeForSearchLoose(row.reading || "");
    const meaningNorm = normalizeForSearchLoose(row.meaning || "");
    let score = 0;
    if (termNorm === q) score += 220;
    if (readingNorm === q) score += 200;
    if (termNorm.includes(q) || q.includes(termNorm)) score += 90;
    if (readingNorm && (readingNorm.includes(q) || q.includes(readingNorm))) score += 70;
    if (meaningNorm.includes(q)) score += 30;
    if (score > bestScore) {
      best = row;
      bestScore = score;
    }
  }
  if (!best || bestScore <= 0) {
    return json({ ok: false, code: "NOT_FOUND", message: "該当する単語が見つかりません。" }, 404);
  }
  return json({
    ok: true,
    term: String(best.term || ""),
    reading: String(best.reading || ""),
    meaning: String(best.meaning || ""),
    examples: Array.isArray(best.examples) ? best.examples : [],
    related: [],
    source: "data_pack.vocab"
  }, 200);
}

async function handleInsightSummarize(request, env) {
  const body = await readJsonBody(request, 64 * 1024);
  const sinceMs = Number(body?.since ? Date.parse(String(body.since)) : NaN);
  const untilMs = Number(body?.until ? Date.parse(String(body.until)) : NaN);
  const topic = toSafeString(body?.topic || "", 200);
  const limit = clampInt(body?.limit || 20, 1, 100);
  const topicNorm = normalizeForSearchLoose(topic);
  const pack = await loadDataPack(env);
  const items = (Array.isArray(pack.insights) ? pack.insights : [])
    .filter((it) => !Number.isFinite(sinceMs) || Number(it.updatedAt || 0) >= sinceMs)
    .filter((it) => !Number.isFinite(untilMs) || Number(it.updatedAt || 0) <= untilMs)
    .filter((it) => !topicNorm || normalizeForSearchLoose([it.title, it.text, JSON.stringify(it.metrics || {}), (it.tags || []).join(" ")].join(" ")).includes(topicNorm))
    .sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0))
    .slice(0, limit);
  if (!items.length) {
    return json({
      ok: true,
      summary: "条件に一致するインサイト記録がありません。",
      items: [],
      source: "data_pack.insights"
    }, 200);
  }
  const viewItems = items.map((it) => ({
    id: it.id,
    type: "insights",
    title: it.title,
    url: it.url || "",
    snippet: makeSnippet([it.text, JSON.stringify(it.metrics || {})].filter(Boolean).join(" "), topic || it.title, 220),
    tags: Array.isArray(it.tags) ? it.tags.slice(0, 8) : [],
    updatedAt: Number(it.updatedAt || 0)
  }));
  const lines = viewItems.slice(0, 8).map((it) => `- ${it.title} (${new Date(Number(it.updatedAt || Date.now())).toISOString().slice(0, 10)}): ${it.snippet}`);
  const summary = `インサイト記録を要約しました。\n${lines.join("\n")}`;
  return json({
    ok: true,
    summary,
    items: viewItems,
    source: "data_pack.insights"
  }, 200);
}

async function handleAdminUploadPack(request, env) {
  const body = await readJsonBody(request, 1024 * 1024);
  const expectedToken = String(env.DATA_PACK_ADMIN_TOKEN || env.ADMIN_KEY || "").trim();
  if (!expectedToken) {
    return json({ ok: false, code: "ADMIN_TOKEN_NOT_CONFIGURED", message: "管理トークンが未設定です。" }, 500);
  }
  const headerToken = String(request.headers.get("x-admin-token") || "").trim();
  const bearer = String(request.headers.get("Authorization") || "").trim().replace(/^Bearer\s+/i, "");
  const bodyToken = String(body?.adminToken || body?.token || "").trim();
  const incoming = headerToken || bearer || bodyToken;
  if (!incoming || incoming !== expectedToken) {
    return json({ ok: false, code: "FORBIDDEN", message: "管理者トークンが不正です。" }, 403);
  }
  const rawPack = (body?.data_pack && typeof body.data_pack === "object")
    ? body.data_pack
    : ((body?.pack && typeof body.pack === "object") ? body.pack : body);
  if (!rawPack || typeof rawPack !== "object") {
    return json({ ok: false, code: "BAD_REQUEST", message: "data_pack が不正です。" }, 400);
  }
  const sourceId = toSafeString(body?.source_id || rawPack?.source_id || "admin-upload", 120) || "admin-upload";
  const normalized = normalizeDataPack(rawPack, sourceId);
  const saved = await saveDataPack(env, normalized);
  return json({
    ok: true,
    message: "data_pack を更新しました。",
    counts: packCounts(saved),
    updatedAt: saved.updatedAt,
    source_id: saved.source_id
  }, 200);
}

