async function handleUserBackupPost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Number(user.uid || 0);
  if (!Number.isFinite(uid) || uid <= 0) {
    return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  }
  const body = await readJsonBody(request, USER_BACKUP_LIMIT_BYTES);
  const payload = (body && typeof body === "object" && body.backup && typeof body.backup === "object")
    ? body.backup
    : body;
  if (!payload || typeof payload !== "object") {
    return json({ code: "BAD_REQUEST", message: "backup が不正です。" }, 400);
  }
  let backupJson = "";
  try {
    backupJson = JSON.stringify(payload);
  } catch {
    return json({ code: "BAD_REQUEST", message: "backup のJSON化に失敗しました。" }, 400);
  }
  const size = new TextEncoder().encode(backupJson).length;
  if (size > USER_BACKUP_LIMIT_BYTES) {
    return json({ code: "PAYLOAD_TOO_LARGE", message: "backup が大きすぎます。" }, 413);
  }
  const updatedAtMs = Math.max(0, Number(payload?.createdAt || Date.now()));
  await env.DB
    .prepare(`
      INSERT INTO user_backups (user_id, backup_json, updated_at)
      VALUES (?1, ?2, ?3)
      ON CONFLICT(user_id) DO UPDATE SET
        backup_json = excluded.backup_json,
        updated_at = excluded.updated_at
    `)
    .bind(uid, backupJson, updatedAtMs)
    .run();
  return json({ ok: true, updatedAtMs }, 200);
}

function normalizeSyncItem(raw) {
  const obj = (raw && typeof raw === "object") ? raw : null;
  if (!obj) return null;
  const id = String(obj.id || "").trim();
  if (!id) return null;
  const updatedAt = Math.max(0, Number(obj.updatedAt ?? obj.updated_at ?? obj.ts ?? obj.createdAt ?? 0)) || Date.now();
  const deletedAt = Math.max(0, Number(obj.deletedAt ?? obj.deleted_at ?? 0)) || 0;
  return {
    id,
    updatedAt,
    deletedAt,
    data: { ...obj, id, updatedAt, deletedAt }
  };
}

function mergeSettingsPatch(existingRaw, patchRaw) {
  const base = (existingRaw && typeof existingRaw === "object") ? existingRaw : {};
  const patch = (patchRaw && typeof patchRaw === "object") ? patchRaw : {};
  const out = { ...base };
  for (const [key, val] of Object.entries(patch)) {
    if (key === "updatedAt" || key === "updated_at") continue;
    if (val === undefined) continue;
    out[key] = val;
  }
  return out;
}

async function handleSyncSnapshot(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Number(user.uid || 0);
  if (!Number.isFinite(uid) || uid <= 0) {
    return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  }
  const parseRows = (rows) => {
    const list = [];
    for (const r of (rows || [])) {
      let data = null;
      try {
        data = JSON.parse(String(r?.data_json || "null"));
      } catch {
        data = null;
      }
      if (!data || typeof data !== "object") data = {};
      const id = String(data.id || r?.id || "").trim();
      if (!id) continue;
      const updatedAt = Math.max(0, Number(data.updatedAt || data.updated_at || r?.updated_at || 0));
      const deletedAt = Math.max(0, Number(data.deletedAt || data.deleted_at || r?.deleted_at || 0));
      list.push({ ...data, id, updatedAt, deletedAt });
    }
    return list;
  };
  const insightsRows = await env.DB.prepare("SELECT id, data_json, updated_at, deleted_at FROM sync_insights WHERE user_id = ?1").bind(uid).all();
  const presetsRows = await env.DB.prepare("SELECT id, data_json, updated_at, deleted_at FROM sync_presets WHERE user_id = ?1").bind(uid).all();
  const chatsRows = await env.DB.prepare("SELECT id, data_json, updated_at, deleted_at FROM sync_chats WHERE user_id = ?1").bind(uid).all();
  const settingsRow = await env.DB.prepare("SELECT data_json, updated_at FROM sync_settings WHERE user_id = ?1 LIMIT 1").bind(uid).first();
  let settings = {};
  let settingsUpdatedAt = 0;
  if (settingsRow) {
    try {
      settings = JSON.parse(String(settingsRow.data_json || "null")) || {};
    } catch {
      settings = {};
    }
    settingsUpdatedAt = Math.max(0, Number(settingsRow.updated_at || 0));
  }
  return json({
    ok: true,
    snapshot: {
      insights: parseRows(insightsRows?.results || []),
      presets: parseRows(presetsRows?.results || []),
      chats: parseRows(chatsRows?.results || []),
      settings: (settings && typeof settings === "object") ? settings : {},
      settingsUpdatedAt
    }
  }, 200);
}

async function handleSyncUpsert(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Number(user.uid || 0);
  if (!Number.isFinite(uid) || uid <= 0) {
    return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  }
  const body = await readJsonBody(request, SYNC_BODY_LIMIT_BYTES);
  const payload = (body && typeof body === "object") ? body : {};
  const insightsRaw = Array.isArray(payload.insights) ? payload.insights : [];
  const presetsRaw = Array.isArray(payload.presets) ? payload.presets : [];
  const chatsRaw = Array.isArray(payload.chats) ? payload.chats : [];
  const settingsPatch = (payload.settingsPatch && typeof payload.settingsPatch === "object") ? payload.settingsPatch : null;

  const upsertList = async (table, items) => {
    let applied = 0;
    for (const raw of items) {
      const item = normalizeSyncItem(raw);
      if (!item) continue;
      const row = await env.DB.prepare(`SELECT updated_at, deleted_at FROM ${table} WHERE user_id = ?1 AND id = ?2 LIMIT 1`).bind(uid, item.id).first();
      const prevUpdated = Math.max(0, Number(row?.updated_at || 0));
      const prevDeleted = Math.max(0, Number(row?.deleted_at || 0));
      const incomingVer = Math.max(item.updatedAt, item.deletedAt || 0);
      const existingVer = Math.max(prevUpdated, prevDeleted);
      if (!row || incomingVer >= existingVer) {
        const dataJson = JSON.stringify(item.data);
        await env.DB.prepare(`
          INSERT INTO ${table} (user_id, id, data_json, updated_at, deleted_at)
          VALUES (?1, ?2, ?3, ?4, ?5)
          ON CONFLICT(user_id, id) DO UPDATE SET
            data_json = excluded.data_json,
            updated_at = excluded.updated_at,
            deleted_at = excluded.deleted_at
        `).bind(uid, item.id, dataJson, item.updatedAt, item.deletedAt || 0).run();
        applied += 1;
      }
    }
    return applied;
  };

  const appliedInsights = await upsertList("sync_insights", insightsRaw);
  const appliedPresets = await upsertList("sync_presets", presetsRaw);
  const appliedChats = await upsertList("sync_chats", chatsRaw);

  let settingsApplied = false;
  if (settingsPatch) {
    let existing = {};
    let prevUpdatedAt = 0;
    const row = await env.DB.prepare("SELECT data_json, updated_at FROM sync_settings WHERE user_id = ?1 LIMIT 1").bind(uid).first();
    if (row) {
      try {
        existing = JSON.parse(String(row.data_json || "null")) || {};
      } catch {
        existing = {};
      }
      prevUpdatedAt = Math.max(0, Number(row.updated_at || 0));
    }
    const incomingUpdatedAt = Math.max(0, Number(settingsPatch.updatedAt || settingsPatch.updated_at || Date.now()));
    const merged = mergeSettingsPatch(existing, settingsPatch);
    const finalUpdatedAt = Math.max(prevUpdatedAt, incomingUpdatedAt);
    const mergedJson = JSON.stringify(merged);
    await env.DB.prepare(`
      INSERT INTO sync_settings (user_id, data_json, updated_at)
      VALUES (?1, ?2, ?3)
      ON CONFLICT(user_id) DO UPDATE SET
        data_json = excluded.data_json,
        updated_at = excluded.updated_at
    `).bind(uid, mergedJson, finalUpdatedAt).run();
    settingsApplied = true;
  }

  return json({
    ok: true,
    applied: {
      insights: appliedInsights,
      presets: appliedPresets,
      chats: appliedChats,
      settings: settingsApplied
    }
  }, 200);
}

