async function handleQreditPurchasePost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, qreditSafeInt(user.uid || 0, 0));
  const body = await readJsonBody(request, 16 * 1024);
  const packId = String(body?.packId || "").trim();
  const idempotencyKey = String(body?.idempotencyKey || body?.requestId || "").trim();
  if (!packId) return json({ code: "BAD_REQUEST", message: "packId が必要です。" }, 400);
  if (!idempotencyKey) return json({ code: "IDEMPOTENCY_REQUIRED", message: "idempotencyKey が必要です。" }, 400);
  const now = Date.now();
  const [campaignRow, packRows] = await Promise.all([
    qreditLoadActiveCampaignRow(env, now),
    qreditLoadPackRows(env, now)
  ]);
  const packRow = packRows.find((row) => String(row?.id || "") === packId);
  if (!packRow) return json({ code: "PACK_NOT_FOUND", message: "購入パックが見つかりません。" }, 404);
  const campaign = qreditBuildCampaignPayload(campaignRow, now);
  const pack = qreditPackRowToPayload(packRow, campaign);
  const grant = await qreditGrant(env, {
    userId: uid,
    amount: pack.grantedQredit,
    type: QREDIT_LEDGER_TYPES.PURCHASE,
    reasonCode: `purchase:${pack.id}`,
    referenceId: `purchase:${pack.id}:${now}`,
    idempotencyKey,
    createdBy: "purchase",
    meta: {
      packId: pack.id,
      priceJpy: pack.price,
      baseQredit: pack.baseQredit,
      grantedQredit: pack.grantedQredit,
      campaignActive: !!campaign.active,
      campaignId: String(campaign.id || ""),
      paymentMode: "mock"
    }
  });
  if (!grant.ok && grant.code === "QREDIT_PENDING_MUTATION") {
    return json({ code: grant.code, message: "購入処理が完了するまでしばらくお待ちください。" }, 409);
  }
  const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now });
  return json({
    ok: true,
    purchase: {
      packId: pack.id,
      priceJpy: pack.price,
      baseQredit: pack.baseQredit,
      grantedQredit: pack.grantedQredit,
      bonusQredit: pack.bonusQredit,
      campaignActive: pack.campaignActive,
      paymentMode: "mock"
    },
    qredit
  }, 200);
}

async function handleQreditSubscriptionPost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, qreditSafeInt(user.uid || 0, 0));
  const body = await readJsonBody(request, 16 * 1024);
  const planId = normalizeSubscriptionPlanId(body?.planId);
  const method = String(body?.method || "").trim().toLowerCase();
  const idempotencyKey = String(body?.idempotencyKey || body?.requestId || "").trim();
  if (!planId || !QREDIT_PLAN_RULES[planId]) {
    return json({ code: "BAD_PLAN", message: "planId が不正です。" }, 400);
  }
  if (method !== "qredit" && method !== "mock_cash") {
    return json({ code: "BAD_METHOD", message: "method が不正です。" }, 400);
  }
  const result = await qreditActivateSubscription(env, {
    userId: uid,
    planId,
    method,
    idempotencyKey,
    now: Date.now()
  });
  if (!result.ok) {
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now: Date.now() });
    const status = result.code === "QREDIT_INSUFFICIENT" ? 402 : 409;
    return json({
      code: result.code || "SUBSCRIPTION_FAILED",
      message: result.code === "QREDIT_INSUFFICIENT"
        ? `${QREDIT_LABEL}残高が足りません。`
        : "サブスク加入を完了できませんでした。",
      required: qreditSafeInt(result.required || 0, 0),
      balance: qreditSafeInt(result.balance || qredit?.balance || 0, 0),
      subscription: result.subscription || null,
      qredit
    }, status);
  }
  const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now: Date.now() });
  return json({
    ok: true,
    subscription: result.subscription || qredit?.subscription || null,
    qredit
  }, 200);
}

async function handleQreditUnlockPost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, qreditSafeInt(user.uid || 0, 0));
  const body = await readJsonBody(request, 16 * 1024);
  const unlockKey = String(body?.unlockKey || "").trim();
  const idempotencyKey = String(body?.idempotencyKey || body?.requestId || "").trim();
  if (unlockKey !== QREDIT_UNLOCK_KEYS.OEA_PACK) {
    return json({ code: "BAD_UNLOCK_KEY", message: "unlockKey が不正です。" }, 400);
  }
  if (!idempotencyKey) {
    return json({ code: "IDEMPOTENCY_REQUIRED", message: "idempotencyKey が必要です。" }, 400);
  }
  const unlocks = await qreditLoadUnlockSet(env, uid);
  if (unlocks.has(unlockKey)) {
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now: Date.now() });
    return json({ ok: true, unlocked: true, unlockKey, qredit }, 200);
  }
  const spend = await qreditSpend(env, {
    userId: uid,
    amount: QREDIT_COSTS.oea_pack_unlock,
    type: QREDIT_LEDGER_TYPES.UNLOCK_OEA_PACK,
    reasonCode: "unlock:oea_pack",
    referenceId: `unlock:${unlockKey}`,
    idempotencyKey,
    createdBy: "system",
    meta: { unlockKey }
  });
  if (!spend.ok) {
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now: Date.now() });
    return json({
      code: spend.code || "QREDIT_UNLOCK_FAILED",
      message: spend.code === "QREDIT_INSUFFICIENT"
        ? `${QREDIT_LABEL}残高が足りません。`
        : "アンロックに失敗しました。",
      required: QREDIT_COSTS.oea_pack_unlock,
      balance: qreditSafeInt(spend.balance || qredit?.balance || 0, 0),
      qredit
    }, spend.code === "QREDIT_INSUFFICIENT" ? 402 : 409);
  }
  await env.DB.prepare(`
    INSERT INTO user_unlocks (user_id, unlock_key, unlocked_at, source_ledger_id)
    VALUES (?1, ?2, ?3, ?4)
    ON CONFLICT(user_id, unlock_key) DO NOTHING
  `).bind(uid, unlockKey, Date.now(), String(spend.ledger?.id || "")).run();
  const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now: Date.now() });
  return json({ ok: true, unlocked: true, unlockKey, qredit }, 200);
}

async function handleQreditExamSessionPost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, qreditSafeInt(user.uid || 0, 0));
  const body = await readJsonBody(request, 8 * 1024);
  const presetId = String(body?.presetId || "").trim();
  const questionTotal = Math.max(1, qreditSafeInt(body?.questionTotal || body?.totalQuestions || 0, 0));
  const ownerUserId = Math.max(0, qreditSafeInt(body?.ownerUserId || 0, 0));
  const eligible = qreditCanRewardPreset(presetId, ownerUserId, uid);
  if (!eligible) {
    return json({ ok: true, eligible: false }, 200);
  }
  const now = Date.now();
  const sessionId = `qex:${crypto.randomUUID()}`;
  const idempotencyKey = `exam_session:${uid}:${presetId}:${now}`;
  await env.DB.prepare(`
    INSERT INTO qredit_exam_reward_sessions (
      id, user_id, preset_id, question_total, status, created_at, expires_at, completed_at, rewarded_at, idempotency_key
    ) VALUES (?1, ?2, ?3, ?4, 'issued', ?5, ?6, 0, 0, ?7)
  `).bind(
    sessionId,
    uid,
    presetId,
    questionTotal,
    now,
    now + QREDIT_EXAM_SESSION_TTL_MS,
    idempotencyKey
  ).run();
  return json({
    ok: true,
    eligible: true,
    sessionId,
    expiresAt: now + QREDIT_EXAM_SESSION_TTL_MS,
    minDurationMs: Math.max(QREDIT_EXAM_MIN_DURATION_MS, questionTotal * 1500)
  }, 200);
}

async function handleQreditExamCompletePost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, qreditSafeInt(user.uid || 0, 0));
  const body = await readJsonBody(request, 12 * 1024);
  const sessionId = String(body?.sessionId || "").trim();
  if (!sessionId) return json({ code: "BAD_REQUEST", message: "sessionId が必要です。" }, 400);
  const now = Date.now();
  const session = await env.DB.prepare(`
    SELECT id, user_id, preset_id, question_total, status, created_at, expires_at, completed_at, rewarded_at
    FROM qredit_exam_reward_sessions
    WHERE id = ?1
      AND user_id = ?2
    LIMIT 1
  `).bind(sessionId, uid).first().catch(() => null);
  if (!session?.id) return json({ code: "NOT_FOUND", message: "報酬セッションが見つかりません。" }, 404);
  if (Number(session.rewarded_at || 0) > 0) {
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now });
    return json({ ok: true, rewarded: false, reason: "already_rewarded", qredit }, 200);
  }
  if (Number(session.expires_at || 0) > 0 && Number(session.expires_at || 0) < now) {
    await env.DB.prepare(`
      UPDATE qredit_exam_reward_sessions
      SET status = 'expired',
          completed_at = ?2
      WHERE id = ?1
    `).bind(sessionId, now).run().catch(() => null);
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now });
    return json({ ok: true, rewarded: false, reason: "expired", qredit }, 200);
  }
  const completed = body?.completed !== false;
  const answeredCount = Math.max(0, qreditSafeInt(body?.answeredCount || body?.questionTotal || 0, 0));
  const durationMs = Math.max(0, qreditSafeInt(body?.durationMs || 0, 0));
  const minDurationMs = Math.max(QREDIT_EXAM_MIN_DURATION_MS, Math.max(1, qreditSafeInt(session.question_total || 1, 1)) * 1500);
  let reason = "";
  if (!completed) reason = "incomplete";
  else if (answeredCount < Math.max(1, qreditSafeInt(session.question_total || 1, 1))) reason = "not_finished";
  else if (durationMs < minDurationMs) reason = "too_fast";
  if (!reason) {
    const latestReward = await env.DB.prepare(`
      SELECT rewarded_at
      FROM qredit_exam_reward_sessions
      WHERE user_id = ?1
        AND preset_id = ?2
        AND rewarded_at > 0
      ORDER BY rewarded_at DESC
      LIMIT 1
    `).bind(uid, String(session.preset_id || "")).first().catch(() => null);
    if (Number(latestReward?.rewarded_at || 0) > (now - QREDIT_EXAM_SAME_PRESET_COOLDOWN_MS)) {
      reason = "cooldown";
    }
  }
  if (!reason) {
    const rewardedToday = await qreditLoadExamRewardToday(env, uid, now);
    if ((rewardedToday + QREDIT_EXAM_REWARD_AMOUNT) > QREDIT_EXAM_DAILY_CAP) {
      reason = "daily_cap";
    }
  }
  if (reason) {
    await env.DB.prepare(`
      UPDATE qredit_exam_reward_sessions
      SET status = ?2,
          completed_at = ?3
      WHERE id = ?1
    `).bind(sessionId, reason, now).run().catch(() => null);
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now });
    return json({ ok: true, rewarded: false, reason, qredit }, 200);
  }
  const grant = await qreditGrant(env, {
    userId: uid,
    amount: QREDIT_EXAM_REWARD_AMOUNT,
    type: QREDIT_LEDGER_TYPES.EXAM_REWARD,
    reasonCode: `exam_reward:${String(session.preset_id || "")}`,
    referenceId: sessionId,
    idempotencyKey: `exam_reward:${sessionId}`,
    createdBy: "reward",
    meta: {
      presetId: String(session.preset_id || ""),
      questionTotal: Math.max(1, qreditSafeInt(session.question_total || 1, 1)),
      durationMs
    }
  });
  if (!grant.ok) {
    const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now });
    return json({ code: grant.code || "EXAM_REWARD_FAILED", message: "報酬付与に失敗しました。", qredit }, 409);
  }
  await env.DB.prepare(`
    UPDATE qredit_exam_reward_sessions
    SET status = 'rewarded',
        completed_at = ?2,
        rewarded_at = ?2
    WHERE id = ?1
  `).bind(sessionId, now).run().catch(() => null);
  const qredit = await qreditBuildPayload(env, uid, { includeCatalogs: true, includeHistory: false, now });
  return json({
    ok: true,
    rewarded: true,
    amount: QREDIT_EXAM_REWARD_AMOUNT,
    reason: "rewarded",
    qredit
  }, 200);
}

async function handleAdminQreditAdjustPost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user || !isAiAdminUnlimitedUser(user, env)) {
    return json({ code: "FORBIDDEN", message: "管理権限が必要です。" }, 403);
  }
  const body = await readJsonBody(request, 16 * 1024);
  const targetUserId = Math.max(0, qreditSafeInt(body?.userId || body?.targetUserId || 0, 0));
  const amountRaw = qreditSafeInt(body?.amount || 0, 0);
  const idempotencyKey = String(body?.idempotencyKey || body?.requestId || "").trim();
  const reasonCode = toSafeString(body?.reasonCode || "admin_adjustment", 80) || "admin_adjustment";
  const note = toSafeString(body?.note || "", 240);
  if (!targetUserId || !amountRaw) {
    return json({ code: "BAD_REQUEST", message: "userId と amount が必要です。" }, 400);
  }
  if (!idempotencyKey) {
    return json({ code: "IDEMPOTENCY_REQUIRED", message: "idempotencyKey が必要です。" }, 400);
  }
  const createdBy = `admin:${Math.max(0, qreditSafeInt(user.uid || 0, 0))}`;
  const op = amountRaw > 0
    ? await qreditGrant(env, {
      userId: targetUserId,
      amount: amountRaw,
      type: QREDIT_LEDGER_TYPES.ADMIN_ADJUSTMENT,
      reasonCode,
      referenceId: `admin_adjust:${targetUserId}:${Date.now()}`,
      idempotencyKey,
      createdBy,
      meta: { note }
    })
    : await qreditSpend(env, {
      userId: targetUserId,
      amount: Math.abs(amountRaw),
      type: QREDIT_LEDGER_TYPES.ADMIN_ADJUSTMENT,
      reasonCode,
      referenceId: `admin_adjust:${targetUserId}:${Date.now()}`,
      idempotencyKey,
      createdBy,
      meta: { note }
    });
  if (!op.ok) {
    const qredit = await qreditBuildPayload(env, targetUserId, { includeCatalogs: true, includeHistory: false, now: Date.now() });
    return json({
      code: op.code || "ADMIN_QREDIT_ADJUST_FAILED",
      message: op.code === "QREDIT_INSUFFICIENT" ? "対象ユーザーの残高が不足しています。" : "Qredit 調整に失敗しました。",
      qredit
    }, op.code === "QREDIT_INSUFFICIENT" ? 409 : 400);
  }
  const qredit = await qreditBuildPayload(env, targetUserId, { includeCatalogs: true, includeHistory: false, now: Date.now() });
  return json({ ok: true, qredit }, 200);
}

