async function handleSubscriptionNotifyPost(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env).catch(() => null);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, Number(user.uid || 0));
  if (!uid) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const body = await readJsonBody(request, 16 * 1024);
  const planId = normalizeSubscriptionPlanId(body?.planId);
  if (!planId) return json({ code: "BAD_REQUEST", message: "planId が不正です。" }, 400);
  const now = Date.now();
  const notifyInApp = body?.notifyInApp === false ? 0 : 1;
  const notifyWebPush = body?.notifyWebPush === true ? 1 : 0;
  const metaJson = JSON.stringify({
    source: toSafeString(body?.source || "subscription_page", 40),
    installed: !!body?.installed,
    permission: toSafeString(body?.permission || "", 24),
    platform: toSafeString(body?.platform || "", 24)
  });
  await env.DB.prepare(`
    INSERT INTO subscription_notify_interest (
      user_id, plan_id, notify_in_app, notify_web_push, status, created_at, updated_at, notified_at, meta_json
    ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?6, 0, ?7)
    ON CONFLICT(user_id, plan_id) DO UPDATE SET
      notify_in_app = excluded.notify_in_app,
      notify_web_push = CASE WHEN excluded.notify_web_push > 0 THEN 1 ELSE subscription_notify_interest.notify_web_push END,
      status = excluded.status,
      updated_at = excluded.updated_at,
      meta_json = excluded.meta_json
  `).bind(uid, planId, notifyInApp, notifyWebPush, SUBSCRIPTION_NOTIFY_STATUS.ACTIVE, now, metaJson).run();
  return json({
    ok: true,
    plan: {
      planId,
      notifyInApp: !!notifyInApp,
      notifyWebPush: !!notifyWebPush,
      status: SUBSCRIPTION_NOTIFY_STATUS.ACTIVE,
      updatedAt: now
    }
  }, 200);
}

