  const groupId = toSafeString(url.searchParams.get("groupId") || "", 120);
  if (!groupId) return json({ code: "BAD_REQUEST", message: "groupId が不正です。" }, 400);
  const detail = await socialGroupDetail(env, groupId, uid);
