async function handleGroupMemberAdd(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, Number(user.uid || 0));
  if (!uid) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const body = await readJsonBody(request, 40 * 1024);
  const groupId = toSafeString(body?.groupId || "", 120);
  const targetUserId = Math.max(0, Number(body?.userId || body?.targetUserId || 0));
  if (!groupId || !targetUserId) return json({ code: "BAD_REQUEST", message: "groupId / userId が不正です。" }, 400);
  const access = await socialGroupAccess(env, groupId, uid);
  if (!access.found) return json({ code: "NOT_FOUND", message: "グループが見つかりません。" }, 404);
  if (!access.member) return json({ code: "FORBIDDEN", message: "このグループに参加していません。" }, 403);
  if (String(access.role || "") !== "owner") {
    return json({ code: "FORBIDDEN", message: "メンバー追加はグループオーナーのみ可能です。" }, 403);
  }
  const targetExists = await env.DB.prepare("SELECT id FROM users WHERE id = ?1 LIMIT 1").bind(targetUserId).first();
  if (!targetExists?.id) return json({ code: "NOT_FOUND", message: "追加対象のユーザーが見つかりません。" }, 404);
  const existing = await env.DB
    .prepare("SELECT role, deleted_at FROM social_group_members WHERE group_id = ?1 AND user_id = ?2 LIMIT 1")
    .bind(groupId, targetUserId)
    .first()
    .catch(() => null);
  if (existing && Number(existing.deleted_at || 0) === 0) {
    return json({ ok: true, alreadyMember: true, groupId, userId: targetUserId }, 200);
  }
  const memberCountRow = await env.DB
    .prepare("SELECT COUNT(1) AS count FROM social_group_members WHERE group_id = ?1 AND deleted_at = 0")
    .bind(groupId)
    .first()
    .catch(() => null);
  const memberCount = Math.max(0, Number(memberCountRow?.count || 0));
  if (memberCount >= GROUP_MEMBER_LIMIT) {
    return json({
      code: "GROUP_MEMBER_LIMIT",
      message: `グループのメンバーは最大${GROUP_MEMBER_LIMIT}人です。`
    }, 409);
  }
  const now = Date.now();
  const role = String(existing?.role || "") === "owner" ? "owner" : "member";
  await env.DB.prepare(`
    INSERT INTO social_group_members (group_id, user_id, role, created_at, updated_at, deleted_at)
    VALUES (?1, ?2, ?3, ?4, ?5, 0)
    ON CONFLICT(group_id, user_id) DO UPDATE SET
      role = excluded.role,
      updated_at = excluded.updated_at,
      deleted_at = 0
  `).bind(groupId, targetUserId, role, now, now).run();
  await env.DB.prepare("UPDATE social_groups SET updated_at = ?2 WHERE id = ?1").bind(groupId, now).run();
  return json({ ok: true, groupId, userId: targetUserId }, 200);
}

async function handleGroupMessageCreate(request, env) {
  if (!env.DB) return json({ code: "DB_NOT_CONFIGURED", message: "DB が未設定です。" }, 500);
  const user = await resolveAuthUser(request, env);
  if (!user) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const uid = Math.max(0, Number(user.uid || 0));
  if (!uid) return json({ code: "UNAUTHORIZED", message: "ログインが必要です。" }, 401);
  const body = await readJsonBody(request, 40 * 1024);
  const groupId = toSafeString(body?.groupId || "", 120);
  const textBody = toSafeString(body?.body || body?.message || "", GROUP_MESSAGE_MAX);
  if (!groupId || !textBody) return json({ code: "BAD_REQUEST", message: "groupId / body が不正です。" }, 400);
  const access = await socialGroupAccess(env, groupId, uid);
  if (!access.found) return json({ code: "NOT_FOUND", message: "グループが見つかりません。" }, 404);
  if (!access.member) return json({ code: "FORBIDDEN", message: "このグループに参加していません。" }, 403);
  const now = Date.now();
  const id = `gmsg_${crypto.randomUUID().replace(/-/g, "").slice(0, 24)}`;
  const moderationResult = await monitorAndMaybeEnforceContent(env, {
    userId: uid,
    targetType: MONITOR_TARGET_TYPES.GROUP_MESSAGE,
    targetId: id,
    eventType: "ai_flagged_group_message",
    content: textBody
  });
  if (moderationResult?.enforced?.enforcement) {
    return json({
      ok: false,
      code: "GROUP_MESSAGE_BLOCKED",
      message: "メッセージ内容が安全監視により制限対象となりました。",
      enforcement: moderationResult.enforced.enforcement,
      moderation: moderationResult.analysis
    }, 423);
  }
  await env.DB.prepare(`
    INSERT INTO social_group_messages (id, group_id, user_id, body, created_at, updated_at, deleted_at)
    VALUES (?1, ?2, ?3, ?4, ?5, ?6, 0)
  `).bind(id, groupId, uid, textBody, now, now).run();
  await env.DB.prepare("UPDATE social_groups SET updated_at = ?2 WHERE id = ?1").bind(groupId, now).run();
  return json({ ok: true, groupId, messageId: id, createdAt: now }, 200);
}

